CREATE TABLE IF NOT EXISTS public.affiliates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, name text NOT NULL, affiliate_type text NOT NULL DEFAULT 'INDIVIDUAL', phone text, email text, referral_code text NOT NULL, status text NOT NULL DEFAULT 'ACTIVE', payment_method text, payment_account text, tax_number text, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id, referral_code));